# ---------------------------------------------------------------- лаба 8
R = json.load(open("/root/labs/tools/build/data/lab8/summary.json"))
f = lambda v: f"{v:.1f}".replace(".", ",")
rows = [["Пользователей", "Среднее, мс", "Макс., мс", "Запросов в секунду", "Ошибки"]]
for r in R:
    rows.append([str(r["threads"]), f(r["avg"]), str(r["mx"]), f(r["tput"]), f"{r['err']:.0f} %"])
